package com.careerverse.servlet;
import com.careerverse.config.DB; import com.careerverse.dao.UserDAO; import com.careerverse.service.EmailService; import com.careerverse.util.TokenUtil; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.time.*;
@WebServlet("/forgot-password") public class ForgotPasswordServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String email=r.getParameter("email");try{UserDAO.Result u=UserDAO.find(email);if(u!=null){String token=TokenUtil.randomToken();try(Connection c=DB.getConnection();PreparedStatement q=c.prepareStatement("INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,?)")){q.setInt(1,u.id());q.setString(2,TokenUtil.sha256(token));q.setTimestamp(3,Timestamp.from(Instant.now().plusSeconds(15*60)));q.executeUpdate();}String link=r.getRequestURL().toString().replace("/forgot-password","")+"/reset-password?token="+token;try{EmailService.send(email,"CareerVerse AI - Reset Password","Use this link within 15 minutes to reset your password:\n\n"+link);}catch(Exception ignored){}}s.sendRedirect("forgot-password.jsp?sent=1");}catch(Exception e){s.sendRedirect("forgot-password.jsp?error=1");}}}
